rows.indexPatch:
diff --git a/lib/os_setup.c b/lib/os_setup.c
index e3351ffc..7085b166 100644
--- a/lib/os_setup.c
+++ b/lib/os_setup.c
@@ -3072,8 +3072,7 @@ ___HIDDEN void user_intr ___PVOID
 {
   /**** belongs elsewhere */
   /* send interrupt only to processor 0 of vm 0 */
-  ___virtual_machine_state ___vms = &___GSTATE->vmstate0;
-  ___raise_interrupt_pstate (___PSTATE_FROM_PROCESSOR_ID(0,___vms), ___INTR_USER);
+  ___raise_interrupt (___INTR_USER); /* registry-safe, still targets VM0/processor0 */
 }

